    "alloq_offer",
    "alloq_project",
    "alloq_team",
)
EXTRA_MODULES = (
    "app.components.sidebar_state",
    "app.desktop.db_access_state",
    "app.desktop.login_state",
)
OWN_PACKAGES = frozenset({*PACKAGES, "app"})

